@* Vertical tab navigation for settings sections *@

<nav class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@* Profile editing section with save/discard *@

<div class="settings-section">
    <h3>Profile</h3>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="profile-form">
        <div class="avatar-preview">
            <img src="@editModel.AvatarUrl" alt="Avatar" class="avatar-image" />
            <span class="avatar-url">@editModel.AvatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="editModel.DisplayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="editModel.Email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" rows="4" @bind="editModel.Bio"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @(isSaving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="Discard" disabled="@isSaving">
                Discard Changes
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileModel editModel = new();
    private string? successMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (editModel.DisplayName == "" && Profile is not null)
        {
            CopyFromProfile();
        }
    }

    private void CopyFromProfile()
    {
        editModel = new ProfileModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;

        var updated = new UserProfile(editModel.DisplayName, editModel.Email, editModel.AvatarUrl, editModel.Bio);
        await OnSave.InvokeAsync(updated);

        successMessage = "Profile saved successfully!";
        isSaving = false;

        _ = DismissToastAsync();
    }

    private void Discard()
    {
        CopyFromProfile();
        successMessage = null;
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private sealed class ProfileModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@* Notification preferences section *@

<div class="settings-section">
    <h3>Notifications</h3>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="notification-toggles">
        <div class="toggle-row">
            <label class="toggle-label">
                <input type="checkbox" @bind="emailNotifications" />
                <span>Email Notifications</span>
            </label>
            <span class="toggle-description">Receive notifications via email</span>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <input type="checkbox" @bind="pushNotifications" />
                <span>Push Notifications</span>
            </label>
            <span class="toggle-description">Receive browser push notifications</span>
        </div>

        <div class="toggle-row">
            <label class="toggle-label">
                <input type="checkbox" @bind="weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
            <span class="toggle-description">Get a weekly summary of activity</span>
        </div>
    </div>

    <div class="muted-channels">
        <h4>Muted Channels</h4>
        @if (channels.Count == 0)
        {
            <p class="no-channels">No channels available.</p>
        }
        else
        {
            <ul class="channel-list">
                @foreach (var channel in channels)
                {
                    <li class="channel-item">
                        <label>
                            <input type="checkbox"
                                   checked="@channel.IsMuted"
                                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                            <span>@channel.Name</span>
                        </label>
                    </li>
                }
            </ul>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save Preferences")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AvailableChannels { get; set; } = [];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<ChannelModel> channels = [];
    private string? successMessage;
    private bool isSaving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized && Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            channels = AvailableChannels.Select(c => new ChannelModel
            {
                Name = c,
                IsMuted = Prefs.MutedChannels.Contains(c)
            }).ToList();
            initialized = true;
        }
    }

    private void ToggleChannel(ChannelModel channel, bool muted)
    {
        channel.IsMuted = muted;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;

        var mutedChannels = channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await OnSave.InvokeAsync(updated);

        successMessage = "Preferences saved successfully!";
        isSaving = false;

        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private sealed class ChannelModel
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

@* Security settings: password change, 2FA, active sessions *@

<div class="settings-section">
    <h3>Security</h3>

    @if (message is not null)
    {
        <div class="toast @(isError ? "error" : "success")">@message</div>
    }

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="panel-toggle">@(passwordPanelOpen ? "▲" : "▼")</span>
        </button>

        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                </div>

                @if (passwordError is not null)
                {
                    <p class="field-error">@passwordError</p>
                }

                <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@isUpdatingPassword">
                    @(isUpdatingPassword ? "Updating..." : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <div class="toggle-row">
            <label class="toggle-label">
                <input type="checkbox" checked="@Security.TwoFactorEnabled" disabled />
                <span>Two-Factor Authentication</span>
            </label>
            <span class="status-indicator @(Security.TwoFactorEnabled ? "enabled" : "disabled")">
                @(Security.TwoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
            </span>
        </div>
        @if (Security.LastPasswordChange.HasValue)
        {
            <p class="meta-info">Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h4>Active Sessions</h4>

        @if (Security.Sessions.Count == 0)
        {
            <p>No active sessions.</p>
        }
        else
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm"
                                            @onclick="() => ConfirmRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="dialog-overlay" @onclick="CancelRevoke">
            <div class="dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="dialog-actions">
                    <button class="btn btn-danger" @onclick="RevokeSessionAsync" disabled="@isRevoking">
                        @(isRevoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public SecuritySettings Security { get; set; } = default!;

    [Parameter]
    public string CurrentSessionId { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool isUpdatingPassword;

    private ActiveSession? sessionToRevoke;
    private bool isRevoking;

    private string? message;
    private bool isError;

    private async Task UpdatePasswordAsync()
    {
        passwordError = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }

        isUpdatingPassword = true;

        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            message = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
            passwordPanelOpen = false;
        }
        catch (Exception ex)
        {
            message = $"Failed to update password: {ex.Message}";
            isError = true;
        }
        finally
        {
            isUpdatingPassword = false;
            _ = DismissMessageAsync();
        }
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

