toolArgs.file_text:
@* Appearance settings with live preview *@

<div class="settings-section">
    <h3>Appearance</h3>

    @if (successMessage is not null)
    {
        <div class="toast success">@successMessage</div>
    }

    <div class="appearance-controls">
        <!-- Theme Selector -->
        <fieldset class="form-group">
            <legend>Theme</legend>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(selectedTheme == theme)"
                               @onchange="() => selectedTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </fieldset>

        <!-- Font Size Selector -->
        <fieldset class="form-group">
            <legend>Font Size</legend>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(selectedFontSize == size)"
                               @onchange="() => selectedFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </fieldset>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="selectedLanguage">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="toggle-row">
            <label class="toggle-label">
                <input type="checkbox" @bind="compactMode" />
                <span>Compact Mode</span>
            </label>
            <span class="toggle-description">Reduce spacing and padding throughout the UI</span>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Preview</h4>
        <div class="preview-content">
            <p class="preview-text">This is how your content will look with the selected settings.</p>
            <div class="preview-card">
                <strong>Sample Card</strong>
                <p>Here's an example of a card element with your chosen appearance settings applied.</p>
                <button class="btn btn-primary">Sample Button</button>
            </div>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @(isSaving ? "Saving..." : "Save")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Appearance { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private string? successMessage;
    private bool isSaving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized && Appearance is not null)
        {
            selectedTheme = Appearance.Theme;
            selectedFontSize = Appearance.FontSize;
            selectedLanguage = Appearance.Language;
            compactMode = Appearance.CompactMode;
            initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{selectedTheme.ToLowerInvariant()} font-{selectedFontSize.ToLowerInvariant()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        successMessage = null;

        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);

        successMessage = "Appearance settings saved!";
        isSaving = false;

        _ = DismissToastAsync();
    }

    private async Task DismissToastAsync()
    {
        await Task.Delay(3000);
        successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

